/* Product page uses the shared preview catalog and bag. */
(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const {products,brands,imageFrames}=window.UrbanCatalog;const find=id=>products.find(p=>p.id===id);
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let cart=read('urban-preview-cart',[]).filter(v=>find(v.id)&&Number.isInteger(v.qty)&&v.qty>0).map(v=>({...v,qty:Math.min(99,v.qty)}));
let saved=read('urban-preview-wishlist',[]).filter(id=>find(id));let panel='',toastTimer,searchTimer,introDone=false;
const categories={hookahs:'Hookahs',bowls:'Bowls',heat:'Heat management',hoses:'Hoses & tips',care:'Tools & spares',charcoal:'Charcoal'};
const brandName=id=>brands.find(b=>b.id===id)?.name||id;
function art(p){const [x,y,w,h,sw,sh]=imageFrames[p.art];return `<span class="product-art art-${p.art}" role="img" aria-label="${p.name}"><svg class="catalog-photo" viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><image data-photo-src="assets/images/product-cutout-${p.art}.webp" width="${sw}" height="${sh}"/></svg></span>`;}
const photoObserver='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;$$('image[data-photo-src]',entry.target).forEach(img=>{img.setAttribute('href',img.dataset.photoSrc);delete img.dataset.photoSrc;});photoObserver.unobserve(entry.target);}),{rootMargin:'600px 0px'}):null;
function hydrate(){ $$('image[data-photo-src]').forEach(img=>{if(photoObserver)photoObserver.observe(img.closest('.product-art'));else{img.setAttribute('href',img.dataset.photoSrc);delete img.dataset.photoSrc;}}); }
function card(p){const badge=p.badge==='Signature'?'Limited':p.badge==='The edit'?'Bestseller':p.badge?'New':'';return `<article class="product-card" data-id="${p.id}"><div class="product-image"><button class="product-picture" data-product="${p.id}" aria-label="View ${p.name}">${art(p)}</button>${badge?`<span class="product-badge badge-${badge.toLowerCase()}">${badge}</span>`:''}<button class="save-product ${saved.includes(p.id)?'is-saved':''}" data-save="${p.id}" aria-label="Save ${p.name}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button><button class="quick-add" data-add="${p.id}" aria-label="Quick add ${p.name} to bag">Quick add ${icon('plus')}</button></div><div class="product-info"><div><p class="product-type">${p.label}</p><button class="product-name" data-product="${p.id}">${p.name}</button><p class="price">${money(p.price)}</p></div><button class="add-product" data-add="${p.id}" aria-label="Add ${p.name} to bag">${icon('plus')}</button></div></article>`;}
$$('.product-art').forEach(el=>{const index=Number(el.className.match(/art-(\d+)/)?.[1]);if(Number.isInteger(index))el.innerHTML=art(products.find(p=>p.art===index)).replace(/^<span[^>]*>|<\/span>$/g,'');});
function count(){const n=cart.reduce((sum,p)=>sum+p.qty,0);$$('.cart-count').forEach(el=>el.textContent=n);$('.bag-button').setAttribute('aria-label',`Open shopping bag, ${n} items`);}
function persist(){try{localStorage.setItem('urban-preview-cart',JSON.stringify(cart));localStorage.setItem('urban-preview-wishlist',JSON.stringify(saved));}catch{}count();}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
const drawer=$('#shop-dialog'),content=$('#content-dialog'),galleryDialog=$('#gallery-dialog');
function lock(){document.body.classList.toggle('is-locked',!!$('dialog[open]'));}
function open(dialog){if(dialog.open)return;[drawer,content,galleryDialog].forEach(d=>{if(d.open)d.close();});dialog.showModal();lock();}
[drawer,content,galleryDialog].forEach(d=>{d.addEventListener('close',lock);d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});});

const mobileMQ=matchMedia('(max-width:900px)');
function renderPanel(){const body=$('#drawer-body');if(panel==='cart'){body.innerHTML=cart.length?cart.map(row=>{const p=find(row.id);return `<div class="cart-item"><button class="cart-thumb" data-product="${p.id}" aria-label="View ${p.name}">${art(p)}</button><div><h3>${p.name}</h3><p>${money(p.price)}</p><div class="quantity-control"><button data-quantity="${p.id}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${row.qty}</span><button data-quantity="${p.id}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div></div><button class="remove-item" data-remove="${p.id}">Remove</button></div>`;}).join('')+`<div class="cart-summary"><span>Subtotal</span><strong>${money(cart.reduce((s,p)=>s+find(p.id).price*p.qty,0))}</strong></div><a class="view-full-cart" href="cart.html">View full bag ${icon('arrow')}</a><a class="button cart-checkout" href="checkout.html">Checkout ${icon('arrow')}</a><p class="cart-preview-note">Preview bag. No payment will be taken.</p>`:`<div class="empty-state"><h3>Your next favourite is waiting.</h3><p>Your bag is empty. Explore the edit below.</p><button class="button" data-browse>Keep exploring ${icon('arrow')}</button></div>`;}else{body.innerHTML=saved.length?`<div class="wishlist-products">${saved.map(id=>card(find(id))).join('')}</div>`:'<div class="empty-state"><h3>Your saved edit.</h3><p>Tap a heart to keep your favourites here.</p></div>';}hydrate();}
function openPanel(mode){if(mode==='search'){location.href='shop.html';return;}panel=mode;$('#drawer-title').textContent=mode==='cart'?'Your bag.':'Your saved edit.';renderPanel();open(drawer);}
function detail(id){if(id==='studio-black'){location.href='product.html';return;}const p=find(id);if(!p)return;$('#content-body').innerHTML=`<div class="product-detail"><div class="product-detail-image">${art(p)}</div><div><p class="eyebrow">${p.label}</p><h2 id="content-title">${p.name}</h2><p class="detail-price">${money(p.price)}</p><p class="detail-description">${p.description}</p><button class="button" data-add="${p.id}">Add to bag ${icon('bag')}</button><button class="text-link" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" style="margin-top:20px">Save to wishlist ${icon('heart')}</button><small>Preview product and illustrative price. Confirm specifications with the live catalog.</small></div></div>`;hydrate();open(content);}
const info={contact:['Let’s talk.','Store contact channels will be connected before launch.'],shipping:['Shipping & delivery.','Delivery locations, costs and timelines will be published with the live store.'],returns:['Returns & refunds.','The store returns policy will be available before purchases open.'],orders:['Your orders.','Order tracking opens with your live account. This preview does not place orders.'],account:['Your account.','Account access opens with the live store. Your preview wishlist already works locally.'],privacy:['Your privacy.','Bag and wishlist choices stay in this browser. No newsletter email or order is submitted.'],terms:['Terms & conditions.','Real purchase terms will be published before checkout opens.'],age:['For adults only.','Urban Shisha is for adults 18+. Smoking is injurious to health.'],social:['Stay close to the edit.','Social channels will be connected before launch.'],faq:['Good to know.','This is a design preview. Filters, sorting, bag and wishlist work with a sample catalog; checkout opens with the live store.']};
function showInfo(key){const config=window.URBAN_STORE||{},phone=String(config.whatsapp||'').replace(/\D/g,'');if(key==='contact'&&phone.length>=7&&phone.length<=15){window.open('https://wa.me/'+phone,'_blank','noopener,noreferrer');return;}if(key==='social'&&/^https:\/\/(www\.)?instagram\.com\//.test(config.instagram||'')){window.open(config.instagram,'_blank','noopener,noreferrer');return;}const [title,text]=info[key]||info.faq;$('#content-body').innerHTML=`<article class="article-content"><p class="eyebrow">URBAN SHISHA / GOOD TO KNOW</p><h2 id="content-title">${title}</h2><p>${text}</p><button class="button" data-browse>Explore the edit ${icon('arrow')}</button></article>`;open(content);}
const mega=$('#category-menu'),megaToggle=$('#mega-toggle'),header=$('.site-header'),mobile=$('#mobile-nav'),mobileToggle=$('.mobile-toggle');let megaTimer;
function closeMega(){mega.hidden=true;megaToggle.setAttribute('aria-expanded','false');}function openMega(){mega.hidden=false;megaToggle.setAttribute('aria-expanded','true');hydrate();}function closeMenu(){mobile.hidden=true;mobileToggle.setAttribute('aria-expanded','false');mobileToggle.setAttribute('aria-label','Open navigation');mobileToggle.innerHTML=icon('menu');}
megaToggle.addEventListener('click',()=>mega.hidden?openMega():closeMega());megaToggle.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();openMega();$('a',mega).focus();}});megaToggle.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!mobileMQ.matches){clearTimeout(megaTimer);openMega();}});mega.addEventListener('pointerenter',()=>clearTimeout(megaTimer));header.addEventListener('pointerleave',()=>megaTimer=setTimeout(closeMega,180));header.addEventListener('focusout',e=>{if(!header.contains(e.relatedTarget))closeMega();});document.addEventListener('click',e=>{if(!header.contains(e.target))closeMega();});
mobileToggle.addEventListener('click',()=>{const show=mobile.hidden;mobile.hidden=!show;mobileToggle.setAttribute('aria-expanded',show);mobileToggle.setAttribute('aria-label',show?'Close navigation':'Open navigation');mobileToggle.innerHTML=icon(show?'close':'menu');hydrate();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if(!mega.hidden){closeMega();megaToggle.focus();}}});mobileMQ.addEventListener('change',()=>{closeMenu();closeMega();});
const footerMQ=matchMedia('(max-width:600px)');function footerLayout(){$$('.footer-toggle').forEach((b,i)=>{const show=!footerMQ.matches||i===0;b.setAttribute('aria-expanded',show);b.tabIndex=footerMQ.matches?0:-1;$('#'+b.getAttribute('aria-controls')).hidden=!show;});}footerLayout();footerMQ.addEventListener('change',footerLayout);$('#newsletter-form').addEventListener('submit',e=>{e.preventDefault();$('#newsletter-note').textContent='Preview only. Your email has not been submitted.';notify('Subscriptions open with the store');});$('#year').textContent=new Date().getFullYear();
const product=find('studio-black');const gallery=[{type:'studio',name:'Studio cutout',src:'assets/images/product-cutout-0.webp'},{type:'photo',name:'Complete hookah with hose',src:'assets/images/brando/brando-1.png'},{type:'photo',name:'Stem and green line base',src:'assets/images/brando/brando-2.png'},{type:'photo',name:'Hookah with coiled hose',src:'assets/images/brando/brando-3.png'}];let galleryIndex=0,galleryTween;
$('#pdp-price').textContent=money(product.price);$('.pdp-mobile-buy strong').textContent=money(product.price);
$('#gallery-thumbnails').innerHTML=gallery.map((g,i)=>`<button class="pdp-thumbnail" data-gallery-index="${i}" aria-label="Show ${g.name}" aria-pressed="false"><img src="${g.src}" alt="" width="94" height="100"></button>`).join('');
function galleryImage(g){return g.type==='studio'?art(product):`<img src="${g.src}" alt="COCOYAYA Brando: ${g.name}" width="832" height="832">`;}
function showGallery(index,animate=false){galleryIndex=(index+gallery.length)%gallery.length;const g=gallery[galleryIndex];galleryTween?.kill();$('#gallery-art').innerHTML=galleryImage(g);$('.pdp-stage').dataset.view=g.type;const counter=`0${galleryIndex+1} / 0${gallery.length}`;$('#gallery-counter').textContent=counter;$('#zoom-counter').textContent=counter;$('#gallery-enlarged').innerHTML=galleryImage(g);$$('[data-gallery-index]').forEach((b,i)=>b.setAttribute('aria-pressed',i===galleryIndex));hydrate();if(animate){$('#gallery-status').textContent=`${g.name}, image ${galleryIndex+1} of ${gallery.length}`;if(window.gsap&&!reduced())galleryTween=gsap.fromTo('#gallery-art',{x:14,opacity:.35},{x:0,opacity:1,duration:.35,ease:'power3.out',clearProps:'transform,opacity'});}}
showGallery(0);$('#gallery-thumbnails').addEventListener('click',e=>{const b=e.target.closest('[data-gallery-index]');if(b)showGallery(Number(b.dataset.galleryIndex),true);});for(const id of ['gallery-prev','zoom-prev'])$('#'+id).addEventListener('click',()=>showGallery(galleryIndex-1,true));for(const id of ['gallery-next','zoom-next'])$('#'+id).addEventListener('click',()=>showGallery(galleryIndex+1,true));$('#gallery-zoom').addEventListener('click',()=>{if(!suppressZoom)open(galleryDialog);});galleryDialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();showGallery(galleryIndex+1);}if(e.key==='ArrowLeft'){e.preventDefault();showGallery(galleryIndex-1);}});
let downX=0,downY=0,pointerId=null,suppressZoom=false;
const galleryMain=$('#gallery-zoom');galleryMain.addEventListener('pointerdown',e=>{if(e.button!==0)return;downX=e.clientX;downY=e.clientY;pointerId=e.pointerId;suppressZoom=false;});galleryMain.addEventListener('pointerup',e=>{if(pointerId!==e.pointerId)return;const delta=e.clientX-downX;if(Math.abs(delta)>55&&Math.abs(delta)>Math.abs(e.clientY-downY)){suppressZoom=true;showGallery(galleryIndex+(delta<0?1:-1),true);setTimeout(()=>suppressZoom=false,250);}pointerId=null;});galleryMain.addEventListener('pointercancel',()=>pointerId=null);galleryMain.addEventListener('dragstart',e=>e.preventDefault());
$('#pdp-accessory-products').innerHTML=['coconut-charcoal','silicone-hose','tongs'].map(id=>card(find(id))).join('');$('#pdp-related-products').innerHTML=['signature-chrome','compact-emerald','carbon-edition'].map(id=>card(find(id))).join('');
function qty(){const input=$('#product-quantity');const value=Math.max(1,Math.min(99,Math.floor(Number(input.value)||1)));input.value=value;$('#quantity-minus').disabled=value<=1;$('#quantity-plus').disabled=value>=99;return value;}
$('#quantity-minus').addEventListener('click',()=>{$('#product-quantity').value=qty()-1;qty();});$('#quantity-plus').addEventListener('click',()=>{$('#product-quantity').value=qty()+1;qty();});$('#product-quantity').addEventListener('change',qty);qty();
const addTimers=new WeakMap();function add(id,amount,button){if(!find(id))return;const row=cart.find(p=>p.id===id);if(row)row.qty=Math.min(99,row.qty+amount);else cart.push({id,qty:amount});persist();notify(`${amount===1?'Added to your setup':amount+' items added to your setup'}`);if(button){if(!button.dataset.restHtml)button.dataset.restHtml=button.innerHTML;clearTimeout(addTimers.get(button));button.innerHTML=(button.classList.contains('button')?'Added ':'')+icon('check');button.classList.add('is-added');addTimers.set(button,setTimeout(()=>{button.innerHTML=button.dataset.restHtml;button.classList.remove('is-added');},1300));}if(window.gsap&&!reduced())gsap.fromTo('.bag-button',{scale:.9},{scale:1,duration:.4,ease:'back.out(2)',clearProps:'transform'});if(drawer.open&&panel==='cart')renderPanel();}
$('#pdp-add').addEventListener('click',e=>add(product.id,qty(),e.currentTarget));$('#pdp-mobile-add').addEventListener('click',e=>add(product.id,qty(),e.currentTarget));
function syncSaved(){$$('[data-save]').forEach(b=>{const active=saved.includes(b.dataset.save);b.setAttribute('aria-pressed',active);b.classList.toggle('is-saved',active);});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('.close-dialog')){b.closest('dialog').close();return;}if(b.dataset.open){openPanel(b.dataset.open);return;}if(b.dataset.product){detail(b.dataset.product);return;}if(b.dataset.add){add(b.dataset.add,1,b);return;}if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(v=>v!==id):[...saved,id];persist();syncSaved();notify(saved.includes(id)?'Saved to your wishlist':'Removed from your wishlist');if(drawer.open&&panel==='wishlist')renderPanel();return;}if(b.dataset.quantity){const row=cart.find(r=>r.id===b.dataset.quantity);if(row)row.qty=Math.min(99,row.qty+Number(b.dataset.delta));cart=cart.filter(r=>r.qty>0);persist();renderPanel();return;}if(b.dataset.remove){cart=cart.filter(r=>r.id!==b.dataset.remove);persist();renderPanel();return;}if(b.dataset.info){showInfo(b.dataset.info);return;}if(b.dataset.category){location.href='shop.html?category='+encodeURIComponent(b.dataset.category);return;}if(b.dataset.jumpBudget){location.href='shop.html?max=6000';return;}if(b.hasAttribute('data-preview-checkout')){notify('Checkout opens with the live store');return;}if(b.hasAttribute('data-browse')){location.href='shop.html';return;}if(b.matches('.footer-toggle')&&matchMedia('(max-width:600px)').matches){const show=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',show);$('#'+b.getAttribute('aria-controls')).hidden=!show;}});
let motionContext;function entrance(){if(introDone||reduced()||!window.gsap)return;introDone=true;motionContext=gsap.context(()=>{gsap.from('.pdp-gallery,.pdp-buy-panel',{y:25,duration:.7,stagger:.09,ease:'power3.out',clearProps:'transform'});if(window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);ScrollTrigger.batch('.pdp-details .section-heading,.pdp-spec-poster,.pdp-accessories .product-card,.pdp-related .product-card',{start:'top 95%',once:true,onEnter:batch=>gsap.fromTo(batch,{y:20},{y:0,duration:.5,stagger:.04,clearProps:'transform'})});}});}
const motionMQ=matchMedia('(prefers-reduced-motion:reduce)');motionMQ.addEventListener('change',()=>{motionContext?.revert();motionContext=null;galleryTween?.kill();if(window.gsap)gsap.set('#gallery-art',{clearProps:'transform,opacity'});introDone=false;if(!motionMQ.matches)entrance();});
const age=$('#age-dialog');let accepted=false;try{accepted=localStorage.getItem('urban-preview-age')==='accepted';}catch{}age.addEventListener('cancel',e=>e.preventDefault());if(!accepted){age.showModal();lock();}else requestAnimationFrame(entrance);$('#age-accept').addEventListener('click',()=>{try{localStorage.setItem('urban-preview-age','accepted');}catch{}age.close();lock();entrance();});$('#age-decline').addEventListener('click',()=>{$('.age-actions').hidden=true;$('#age-declined').hidden=false;});
let scrollQueued=false;window.addEventListener('scroll',()=>{if(scrollQueued)return;scrollQueued=true;requestAnimationFrame(()=>{header.classList.toggle('is-scrolled',scrollY>30);scrollQueued=false;});},{passive:true});window.addEventListener('pageshow',()=>{cart=read('urban-preview-cart',[]).filter(v=>find(v.id)&&v.qty>0);saved=read('urban-preview-wishlist',[]).filter(find);count();syncSaved();});count();syncSaved();hydrate();
})();
